use std::{fs,io::{Read,Write}};use ppmd_rust::{Ppmd7Encoder,Ppmd7Decoder};
fn main(){let a:Vec<String>=std::env::args().collect();let source=fs::read(&a[1]).unwrap();let order=a.get(3).map(|s|s.parse().unwrap()).unwrap_or(16u32);let bits=a.get(4).map(|s|s.parse().unwrap()).unwrap_or(26u32);let mut enc=Ppmd7Encoder::new(Vec::new(),order,1u32<<bits).unwrap();enc.write_all(&source).unwrap();let stored=enc.finish(false).unwrap();let mut decoder=Ppmd7Decoder::new(stored.as_slice(),order,1u32<<bits).unwrap();let mut replay=vec![0;source.len()];decoder.read_exact(&mut replay).unwrap();assert_eq!(source,replay);let mut packed=vec![75,55,order as u8,bits as u8];packed.extend_from_slice(&stored);fs::write(&a[2],&packed).unwrap();println!("{}",packed.len());}
